# Game status categories
# Change the values as you see fit
STATUS_WIN = 'win'
STATUS_LOSE = 'lose'
STATUS_ONGOING = 'ongoing'


class Hangman:
    def __init__(self, word):
        self.word = word
        self._guesses = []

    def guess(self, char):
        if self.get_status() != STATUS_ONGOING:
            raise ValueError("The game has already ended.")
        self._guesses.append(char)

    @property
    def remaining_guesses(self):
        # The number of guesses that failed to reveal a new letter.
        failures = sum(
            1
            for i, char in enumerate(self._guesses)
            if char not in self.word or char in self._guesses[:i]
        )
        return 9 - failures

    def get_masked_word(self):
        return ''.join(
            char if char in self._guesses else '_'
            for char in self.word
        )

    def get_status(self):
        if all(char in self._guesses for char in self.word):
            return STATUS_WIN
        if self.remaining_guesses < 0:
            return STATUS_LOSE
        return STATUS_ONGOING

